package dev.trentdb.storage;import java.util.*;public record DuckDbPrimitiveColumnMetadata(DuckDbTableCreateInfo.ScalarLogicalType type,List<Segment> dataSegments,List<Segment> validitySegments,Boundary boundary){public DuckDbPrimitiveColumnMetadata{dataSegments=List.copyOf(dataSegments);validitySegments=List.copyOf(validitySegments);}public enum Boundary{BLOCK_PAYLOAD_DECOMPRESSION_UNSUPPORTED}public record Segment(long tupleCount,BlockPointer blockPointer,int compressionType,Statistics statistics){}public record BlockPointer(long blockId,long offset){}public record Statistics(boolean hasNull,boolean hasNoNull,long distinctCount,OptionalLong min,OptionalLong max){public Statistics{if(min==null||max==null)throw new IllegalArgumentException();}}}
